    let inference = select_inference();
    let opts = VersionOptions {
        strict: args.strict,
        allow_empty_changesets: args.allow_empty_changesets,
    };

    // SPIKE: a failed run leaves `refs/callisto/version-base` at its pre-run state; the next run re-plans from a
    // throwaway worktree of that commit and applies the plan to the real tree.
    let resuming = spike_git(&ws.root, &["rev-parse", "--verify", "--quiet", SPIKE_BASE_REF], None).is_some();
    let mut resume_tree = None;
    let plan = if resuming {
        let tmp = std::env::temp_dir().join(format!("callisto-resume-{}", std::process::id()));
        let tmp_s = tmp.to_string_lossy().into_owned();
        spike_git(&ws.root, &["worktree", "add", "--detach", &tmp_s, SPIKE_BASE_REF], None).expect("worktree");
        let prefix = spike_git(&ws.root, &["rev-parse", "--show-prefix"], None).unwrap_or_default();
        let snap_global = GlobalArgs {
            cwd: tmp.join(prefix.trim()),
            ..global.clone()
        };
        let snap_ws = load_workspace(&snap_global, &runner)?;
        let plan = callisto_graph::commands::plan_version_dated(&snap_ws, &inference, &opts, Some(&today_utc()))?;
        resume_tree = Some(tmp_s);
        plan
    } else {
        callisto_graph::commands::check_partial_run(&ws)?;
        callisto_graph::commands::plan_version_dated(&ws, &inference, &opts, Some(&today_utc()))?
    };

